var items = []
var capacity = 4
var health = 60
var max_health = 100

func pick_up(name):
	if items.size() < capacity:
		items.append(name)
		return true
	return false

func has(name):
	for item in items:
		if item == name:
			return true
	return false

func count(name):
	var total = 0
	for item in items:
		if item == name:
			total += 1
	return total

func heal(amount):
	health += amount
	if health > max_health:
		health = max_health

func use(name):
	var position = items.find(name)
	if position == -1:
		return false
	items.remove_at(position)
	if name == "potion":
		heal(30)
	return true
